new CustomerRequest("DAY03_NINA_FINALE","Nina Faísca","Esse show nasceu dos encontros do bairro. Quero levar esse território comigo. O refletor precisa encontrar minha parte de cima; da cintura pra baixo, deixo a luz descansar. E meu cabelo já tem coreografia: não vamos colocar teto nele.",new[]{"Que encontros você quer representar?","Como você imagina a roupa no palco?"},new[]{"A praça, a quadra, a pista. Esses lugares onde a gente chega separado e acaba fazendo alguma coisa junto.","Em cima, algo claro pra pegar o refletor. Embaixo, escuro pra minha silhueta ficar marcada."},new[]{"Parte de cima clara e parte de baixo escura","Pelo menos uma peça do COMMON GROUND","Sem acessório na cabeça"},"O bairro fez o som. A DripLab entrou no figurino.","Palco do terraço")
